// Ikony liniowe Biblioteki (#162): własny, spójny zestaw – siatka 24 × 24, jedna grubość linii (1,5),
// zaokrąglone końce i narożniki, bez wypełnień. Po wstawieniu to zwykła ścieżka: kolor i grubość linii
// zmienia się w panelu (Obrys); przy powiększaniu linia rośnie razem z ikoną (wygląd zostaje ten sam).
//
// Rysunki w poleceniach bezwzględnych M L H V C Q A Z (patrz przenies() w js/biblioteka-sklad.js).

import { okrag, prost, f } from './biblioteka-sklad.js';
import { t } from './jezyk.js';

const c = (x, y, r) => okrag(x, y, r);
const r = (x, y, w, h, rr = 0) => prost(x, y, w, h, rr);
const l = (...p) => {
  let d = `M ${p[0]} ${p[1]}`;
  for (let i = 2; i < p.length; i += 2) d += ` L ${p[i]} ${p[i + 1]}`;
  return d;
};
const kropki = (lista, rr = 0.6) => lista.map(([x, y]) => c(x, y, rr)).join(' ');
const S = (...czesci) => czesci.join(' ');

// Wspólne kształty kilku ikon.
const CHMURA = 'M7 14 H17 C19.2 14 21 12.2 21 10 C21 7.9 19.4 6.2 17.4 6 C16.6 4.3 14.9 3 13 3 C10.6 3 8.6 4.8 8.2 7.1 C6.4 7.4 5 9 5 10.9 C5 12.6 6 14 7 14 Z';
