const KALENDARZ = S(r(3, 5, 18, 16, 2), l(3, 10, 21, 10), l(8, 3, 8, 7), l(16, 3, 16, 7));
const DOM = S(l(3, 11, 12, 3, 21, 11), 'M5 9.5 V21 H19 V9.5');

// Rysunki liczone (okrąg z punktów, płatki, ziarna, zęby koła).
const naOkregu = (n, cx, cy, R, fn) => Array.from({ length: n }, (_, i) => { const a = (i / n) * Math.PI * 2 - Math.PI / 2; return fn(cx + R * Math.cos(a), cy + R * Math.sin(a), a); }).join(' ');
const ROZANIEC = S(naOkregu(12, 12, 9, 6.5, (x, y) => c(x, y, 0.9)), l(12, 15.5, 12, 18), l(12, 18, 12, 22.5), l(10, 20, 14, 20));
const KWIAT = S(naOkregu(6, 12, 10, 4.2, (x, y) => c(x, y, 2.4)), c(12, 10, 1.6), 'M12 15 C12 18 11.5 20 10.5 22');
const KLOS = S(l(12, 22, 12, 3), ...[6, 9.5, 13, 16.5].flatMap((y) => [
  `M 12 ${y + 2} C 9.5 ${y + 1.5} 8.5 ${y - 0.5} 9 ${y - 2} C 10.8 ${y - 1.4} 11.8 ${y} 12 ${y + 2} Z`,
  `M 12 ${y + 2} C 14.5 ${y + 1.5} 15.5 ${y - 0.5} 15 ${y - 2} C 13.2 ${y - 1.4} 12.2 ${y} 12 ${y + 2} Z`,
]), 'M12 4 C11.2 3 11.4 1.8 12 1.2 C12.6 1.8 12.8 3 12 4 Z');
function zebate() {
  const n = 8; const R = 9; const Rw = 6.8; let d = '';
  for (let i = 0; i < n * 4; i += 1) {
    const a = (i / (n * 4)) * Math.PI * 2;
    const rr = (i % 4 === 1 || i % 4 === 2) ? R : Rw;
    d += `${i ? ' L' : 'M'} ${f(12 + rr * Math.cos(a))} ${f(12 + rr * Math.sin(a))}`;
  }
  return `${d} Z ${c(12, 12, 3)}`;
}

